<script>
document.addEventListener('DOMContentLoaded', () => {
    if (typeof Chart === 'undefined') return;
    const rows = @json($priority), colors = ['#22c55e','#eab308','#f97316','#ef4444'];
    new Chart(document.getElementById('floodPriorityChart'), {type:'scatter',data:{datasets:[{label:'Barangay',data:rows.filter(r=>r.rate !== null).map(r=>({x:r.count,y:r.rate,barangay:r.barangay})),backgroundColor:'#2563eb',pointRadius:7,pointHoverRadius:10}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:(ctx)=>`${ctx.raw.barangay}: ${ctx.raw.x} observations, ${ctx.raw.y}% C–D`}}},scales:{x:{beginAtZero:true,title:{display:true,text:'Recorded observations'},ticks:{precision:0}},y:{min:0,max:100,title:{display:true,text:'C–D share (%)'}}}}});
    new Chart(document.getElementById('floodCodeStackChart'), {type:'bar',data:{labels:rows.map(r=>r.barangay),datasets:['A','B','C','D'].map((code,i)=>({label:`Code ${code}`,data:rows.map(r=>r.codes[code]),backgroundColor:colors[i],borderRadius:3}))},options:{responsive:true,maintainAspectRatio:false,indexAxis:'y',plugins:{legend:{position:'bottom'}},scales:{x:{stacked:true,beginAtZero:true,ticks:{precision:0}},y:{stacked:true}}}});
});
</script>
@endpush
